<?php if($access->can('maintenance.cost.view')): ?><section class="panel"><h2>Jasa Eksternal</h2><?php if($external): ?><div class="table-scroll"><table><thead><tr><th>Penyedia</th><th>Referensi</th><th>Tanggal</th><th>Nilai</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($external as $s): ?><tr><td><?= $e($s['provider_name']) ?></td><td><?= $e($s['service_ref']) ?></td><td><?= $e($s['service_date']) ?></td><td><?= $s['amount']===null?'UNVALUED':\Hls\Http\View::money($s['amount']) ?></td><td><?= $e($s['status']) ?></td><td><?php if($access->can('maintenance.cost.approve')&&in_array($s['status'],['SUBMITTED','RETURNED'],true)): ?><form method="post" class="inline-form"><?= $this->csrf() ?><input type="hidden" name="action" value="external_status"><input type="hidden" name="service_id" value="<?= (int)$s['id'] ?>"><select name="status"><option>APPROVED</option><?php if($s['status']==='SUBMITTED'): ?><option>RETURNED</option><?php endif ?></select><button type="submit">Simpan</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><p>Belum ada jasa eksternal.</p><?php endif ?><?php if($access->can('maintenance.cost.create')): ?><form method="post" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="action" value="external_create"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Penyedia jasa<input name="provider_name" required></label><label>Referensi<input name="service_ref" required></label><label>Dokumen<input name="document_ref"></label><label>Tanggal jasa<input type="date" name="service_date" value="<?= date('Y-m-d') ?>" required></label><label>Nilai biaya<input type="number" name="amount" min="0" step="0.01"></label><label>Deskripsi<textarea name="description" required></textarea></label><label>Catatan<textarea name="note"></textarea></label><button type="submit">Simpan Jasa DRAFT</button></form><?php endif ?></section><?php endif ?>

